  // 作業評分
  float rate_homework = 9;
  // 學習評分
  float rate_learning = 10;

  // 推薦評分
  float rate_recommendation = 11;

}

message ListRatingReq {
  string teacher = 1;
  string subject = 2;
}

message ListRatingRes {
  Rating rating = 1;
}

service ratingService {
  rpc ListRating(ListRatingReq) returns (stream ListRatingRes);
}
